@router.get("/", response_class=HTMLResponse)
async def dashboard(request: Request) -> HTMLResponse:
    """Render the dashboard page with per-instance status cards and search log."""
    apps: list[dict] = []
    settings = request.app.state.settings
    for app_name in APP_TYPES:
        for inst_name in settings.get_enabled_instances(app_name):
            ctx = _build_app_context(request, app_name, inst_name)
            if ctx is not None:
                apps.append(ctx)

    log_entries = log_buffer.get_recent(30)
    stats = await get_dashboard_stats(request.app.state.db)
    time_to_grab = _format_duration(stats["avg_time_to_grab_seconds"])
    health = _build_health_summary(request)
    all_instances = _build_all_instances(settings)
    disclosure = await get_attribution_disclosure(request.app.state.db, view_app=None)

    return templates.TemplateResponse(
        request=request,
        name="dashboard.html",
            # `_on_job_error` / tracking branch — httpx/pydantic exceptions
            # may carry `?apikey=` query strings on legacy *arr installs;
            # aiosqlite/OSError messages do not carry secrets. The exception
            # is logged and swallowed here so the handler always falls through
            # to the TemplateResponse (RESEARCH Pitfall 3: always 200 + card).
            logger.error(
                "{name}/{inst}: Manual search failed -- {exc}",
                name=app_name.title(),
                inst=instance_name,
                exc=(
                    _sanitize_exc(exc)
                    if isinstance(exc, httpx.HTTPError | pydantic.ValidationError)
                    else str(exc)
                ),
            )

    # Return updated card partial
    app_data = _build_app_context(request, app_name, instance_name)
    return templates.TemplateResponse(
        request=request,
        name="partials/app_card.html",
        context={"app": app_data},
    )


@router.post("/api/refresh-counts/{app_name}/{instance_name}", response_class=HTMLResponse)
async def refresh_counts(request: Request, app_name: str, instance_name: str) -> HTMLResponse:
    """Trigger a count-only refresh for a specific instance and return updated card.

    Mirrors search_now field-for-field (guards, rate-limit, lock, tag-cache resolver,
    always-200 card response) minus the search call and failure-counter/last_run semantics.
    Uses sibling last_refresh_time dict so a refresh does not rate-limit a search (D-08).
    The helper return value is DISCARDED; the card is built from the in-place ist mutation.
    Always returns 200 + card even when the helper returns None (fetch OR data fault).
    """
    if len(instance_name) > 64:
            # the rewrite-3 helper handles those internally and returns None; widening
            # the tuple here would mask future helper regressions.
            logger.error(
                "{name}/{inst}: Count refresh failed -- {exc}",
                name=app_name.title(),
                inst=instance_name,
                exc=(
                    _sanitize_exc(exc)
                    if isinstance(exc, httpx.HTTPError | pydantic.ValidationError)
                    else str(exc)
                ),
            )

    # Return updated card partial — built UNCONDITIONALLY from the in-place ist
    # mutation (which the helper has already applied, whether it returned a tuple
    # or None). Always 200 + card; never 500. (Mirrors search_now's always-200.)
    app_data = _build_app_context(request, app_name, instance_name)
    return templates.TemplateResponse(
        request=request,
        name="partials/app_card.html",
        context={"app": app_data},
    )


@router.get("/partials/app-card/{app_name}/{instance_name}", response_class=HTMLResponse)
async def partial_app_card(request: Request, app_name: str, instance_name: str) -> HTMLResponse:
    """Return an HTML fragment for a single app instance status card (htmx partial)."""
    if len(instance_name) > 64:
        return HTMLResponse("Instance name too long", status_code=400)
    app_data = _build_app_context(request, app_name, instance_name)
    if app_data is None:
        return HTMLResponse("")

    return templates.TemplateResponse(
        request=request,
        name="partials/app_card.html",
        context={"app": app_data},
    )


